"""
Interfaces for dependency injection to reduce coupling.

These abstractions define the contracts that concrete implementations
(Database, Config, BinanceAPIManager) must fulfill. Components that
previously depended directly on concrete classes can now depend on
these interfaces, enabling loose coupling, easier testing, and better
separation of concerns.
"""

from abc import ABC, abstractmethod
from datetime import datetime
from typing import Dict, List, Optional

from .models import Coin, CoinValue, CurrentCoin, Pair, ScoutHistory, Trade


class DatabaseInterface(ABC):
    """Interface for database operations."""

    @abstractmethod
    def db_session(self):
        """Context manager providing a SQLAlchemy session."""
        pass

    @abstractmethod
    def set_coins(self, symbols: List[str]):
        """Set the list of supported coins."""
        pass

    @abstractmethod
    def get_coins(self, only_enabled: bool = True) -> List[Coin]:
        """Get all coins (optionally only enabled ones)."""
        pass

    @abstractmethod
    def get_coin(self, coin: str) -> Coin:
        """Get a coin by symbol."""
        pass

    @abstractmethod
    def set_current_coin(self, coin: Coin):
        """Set the current coin being traded."""
        pass

    @abstractmethod
    def get_current_coin(self) -> Optional[Coin]:
        """Get the current coin being traded."""
        pass

    @abstractmethod
    def get_pairs_from(self, from_coin: Coin, only_enabled: bool = True) -> List[Pair]:
        """Get all pairs where from_coin is the source."""
        pass

    @abstractmethod
    def log_scout(
        self,
        pair: Pair,
        target_ratio: float,
        current_coin_price: float,
        other_coin_price: float,
    ):
        """Log scout history entry."""
        pass

    @abstractmethod
    def create_database(self):
        """Create the database schema."""
        pass

    @abstractmethod
    def prune_scout_history(self):
        """Prune old scout history entries."""
        pass

    @abstractmethod
    def prune_value_history(self):
        """Prune old value history entries."""
        pass


class ConfigInterface(ABC):
    """Interface for configuration access."""

    @property
    @abstractmethod
    def BRIDGE(self) -> Coin:
        """Get the bridge coin."""
        pass

    @property
    @abstractmethod
    def BRIDGE_SYMBOL(self) -> str:
        """Get the bridge coin symbol."""
        pass

    @property
    @abstractmethod
    def SUPPORTED_COIN_LIST(self) -> List[str]:
        """Get the list of supported coin symbols."""
        pass

    @property
    @abstractmethod
    def STRATEGY(self) -> str:
        """Get the current trading strategy name."""
        pass

    @property
    @abstractmethod
    def SCOUT_MARGIN(self) -> float:
        """Get the scout margin percentage."""
        pass

    @property
    @abstractmethod
    def SCOUT_MULTIPLIER(self) -> float:
        """Get the scout multiplier."""
        pass

    @property
    @abstractmethod
    def SCOUT_SLEEP_TIME(self) -> int:
        """Get the time to sleep between scouts."""
        pass

    @property
    @abstractmethod
    def USE_MARGIN(self) -> str:
        """Get whether margin trading is enabled."""
        pass

    @property
    @abstractmethod
    def BUY_TIMEOUT(self) -> str:
        """Get the buy timeout setting."""
        pass

    @property
    @abstractmethod
    def SELL_TIMEOUT(self) -> str:
        """Get the sell timeout setting."""
        pass

    @property
    @abstractmethod
    def TESTNET(self) -> bool:
        """Get whether testnet mode is enabled."""
        pass

    @abstractmethod
    def get(self, key: str, default=None):
        """Get a config value by key."""
        pass


class BinanceAPIManagerInterface(ABC):
    """Interface for Binance API operations."""

    @abstractmethod
    def get_ticker_price(self, ticker_symbol: str) -> Optional[float]:
        """Get the ticker price for a symbol."""
        pass

    @abstractmethod
    def get_currency_balance(self, currency_symbol: str) -> float:
        """Get the balance of a specific currency."""
        pass

    @abstractmethod
    def get_fee(self, origin_coin: Coin, target_coin: Coin, selling: bool) -> float:
        """Get the transaction fee for a trade."""
        pass

    @abstractmethod
    def get_min_notional(self, origin_symbol: str, target_symbol: str) -> float:
        """Get the minimum notional value for a trade."""
        pass

    @abstractmethod
    def buy_alt(self, origin_coin: Coin, target_coin: Coin):
        """Buy altcoin."""
        pass

    @abstractmethod
    def sell_alt(self, origin_coin: Coin, target_coin: Coin):
        """Sell altcoin."""
        pass
